import os
import re

# Check for system call patterns in doomgeneric source
for root, dirs, files in os.walk('/app/doomgeneric'):
    for f in files:
        if f.endswith('.c') or f.endswith('.h'):
            path = os.path.join(root, f)
            try:
                with open(path, 'r', errors='ignore') as fh:
                    content = fh.read()
                    # Look for common system call patterns
                    if any(x in content for x in ['syscall', 'open', 'read', 'write', 'mmap', 'brk', 'exit', 'ioctl']):
                        print(f"File: {path}")
                        for i, line in enumerate(content.split('\n'), 1):
                            if any(x in line for x in ['syscall', 'open(', 'read(', 'write(', 'mmap', 'brk', 'exit(', 'ioctl']):
                                if not line.strip().startswith('//'):
                                    print(f"  Line {i}: {line[:100]}")
            except:
                pass
EOF
