  constructor(binaryPath) {
    this.binary = fs.readFileSync(binaryPath);
    this.memory = Buffer.alloc(256 * 1024 * 1024); // 256MB
    this.registers = new Uint32Array(32); // 32 MIPS registers
    this.pc = 0; // Program counter
    this.hi = 0; // HI register
    this.lo = 0; // LO register
    this.loadedSections = [];
    this.fileHandles = new Map();
    this.nextFileHandle = 3;
    this.parseELF();
  }

  parseELF() {
    let offset = 0;

    // Check ELF magic
    const magic = this.binary.readUInt32LE(offset);
    if (magic !== 0x464c457f) {
      throw new Error('Invalid ELF magic');
    }

    // Parse ELF header
    const e_entry = this.binary.readUInt32LE(24);
    const e_phoff = this.binary.readUInt32LE(28);
    const e_phentsize = this.binary.readUInt16LE(42);
    const e_phnum = this.binary.readUInt16LE(44);

    this.pc = e_entry;

    // Load program headers
    for (let i = 0; i < e_phnum; i++) {
      const phOffset = e_phoff + i * e_phentsize;
      const p_type = this.binary.readUInt32LE(phOffset);

      if (p_type === 1) { // PT_LOAD
        const p_offset = this.binary.readUInt32LE(phOffset + 4);
        const p_vaddr = this.binary.readUInt32LE(phOffset + 8);
        const p_filesz = this.binary.readUInt32LE(phOffset + 16);
        const p_memsz = this.binary.readUInt32LE(phOffset + 20);

        // Copy segment into memory
        this.binary.copy(this.memory, p_vaddr, p_offset, p_offset + p_filesz);

        this.loadedSections.push({
