      }
    }
  }

  readMem32(addr) {
    return this.memory.readUInt32LE(addr & 0xFFFFFFFC);
  }

  writeMem32(addr, value) {
    this.memory.writeUInt32LE(value >>> 0, addr & 0xFFFFFFFC);
  }

  readMem8(addr) {
    return this.memory[addr];
  }

  writeMem8(addr, value) {
    this.memory[addr] = value & 0xFF;
  }

  getInstruction(addr) {
    return this.memory.readUInt32LE(addr);
  }

